export enum EscapeMode {
  FULL = 'FULL',
  CONTENT_ONLY = 'CONTENT_ONLY'
}

export type ActionType = 'ESCAPE' | 'UNESCAPE';

export interface ToastState {
  show: boolean;
  message: string;
}

import { EscapeMode } from '../types';

// The specific map provided in the requirements
const escapeMap: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': '&quot;',
  "'": '&#39;',
  "/": '&#x2F;'
};

const unescapeMap: Record<string, string> = {
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  '&quot;': '"',
  '&#39;': "'",
  '&#x2F;': "/"
};

/**
 * Standard escape function using regex replacement
 */
export const escapeStandard = (str: string): string => {
  return String(str).replace(/[&<>"'/]/g, (s) => escapeMap[s] || s);
};

/**
 * Standard unescape function using regex replacement
 */
export const unescapeStandard = (str: string): string => {
  return String(str).replace(/&amp;|&lt;|&gt;|&quot;|&#39;|&#x2F;/g, (s) => unescapeMap[s] || s);
};

/**
 * Smart escape: Splits the string by HTML tags. 
 * Keeps tags intact, escapes text content between them.
 */
export const escapeContentOnly = (str: string): string => {
  // Regex explains:
  // (<[^>]*>) captures anything that looks like an HTML tag (starting with < and ending with >)
  // We split by this group. The resulting array will contain [text, tag, text, tag, text...]
  const parts = str.split(/(<[^>]*>)/g);

  return parts.map(part => {
    // If the part starts with < and ends with >, assume it's a tag and return as is
    if (part.startsWith('<') && part.endsWith('>')) {
      return part;
    }
    // Otherwise, it is content text, so we escape it
    return escapeStandard(part);
  }).join('');
};

/**
 * Main processor function
 */
export const processText = (text: string, action: 'ESCAPE' | 'UNESCAPE', mode: EscapeMode): string => {
  if (!text) return '';

  if (action === 'UNESCAPE') {
    // Unescaping is usually universal regardless of mode for this specific map, 
    // but we apply standard unescape logic.
    return unescapeStandard(text);
  }

  // Action is ESCAPE
  if (mode === EscapeMode.FULL) {
    return escapeStandard(text);
  } else {
    return escapeContentOnly(text);
  }
};

