                : 'text-slate-400 hover:text-white hover:bg-slate-700 disabled:opacity-30'
            }`}
            title="Copy to clipboard"
          >
            {copied ? <Check size={16} /> : <Copy size={16} />}
            {copied && <span className="text-xs font-medium">Copied</span>}
          </button>
        </div>
      </div>

