  isActive?: boolean;
}

export const TextAreaCard: React.FC<TextAreaCardProps> = ({
  id,
  label,
  value,
  onChange,
  readOnly,
  onClear,
  isActive = true
}) => {
  const [copied, setCopied] = React.useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const lineNumbersRef = useRef<HTMLDivElement>(null);

  const handleCopy = async () => {
    if (!value) return;
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy', err);
    }
  };

  // Sync scroll between textarea and line numbers
  const handleScroll = () => {
    if (textareaRef.current && lineNumbersRef.current) {
      lineNumbersRef.current.scrollTop = textareaRef.current.scrollTop;
    }
  };

  // Generate fake line numbers
  const lineCount = value.split('\n').length;
  const lines = Array.from({ length: Math.max(lineCount, 20) }, (_, i) => i + 1);

  return (
    <div className={`flex flex-col h-full border-r last:border-r-0 border-vscode-dark-border dark:border-vscode-dark-border border-vscode-light-border bg-vscode-light-bg dark:bg-vscode-dark-bg`}>

      {/* Editor Tab Bar */}
      <div className="flex items-center bg-vscode-light-tab dark:bg-vscode-dark-tab h-9 border-b border-vscode-light-border dark:border-vscode-dark-border overflow-hidden">
        <div className={`
          flex items-center gap-2 px-3 h-full min-w-[120px] max-w-[200px] text-xs select-none cursor-pointer border-t-2
