interface TextAreaCardProps {
  id: string;
  label: string;
  value: string;
  onChange?: (value: string | undefined) => void;
  placeholder?: string;
  readOnly?: boolean;
  onClear?: () => void;
  language?: string;
  isActive?: boolean;
  isDarkMode?: boolean;
}

export const TextAreaCard: React.FC<TextAreaCardProps> = ({
  id,
  label,
  value,
  onChange,
  readOnly,
  onClear,
  isActive = true,
  isDarkMode = true
}) => {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = async () => {
    if (!value) return;
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy', err);
    }
  };

  return (
    <div className={`flex flex-col h-full border-r last:border-r-0 border-vscode-dark-border dark:border-vscode-dark-border border-vscode-light-border bg-vscode-light-bg dark:bg-vscode-dark-bg`}>

