            ? 'bg-vscode-light-tabActive dark:bg-vscode-dark-tabActive text-vscode-light-textActive dark:text-vscode-dark-textActive border-primary' 
            : 'text-vscode-light-text dark:text-vscode-dark-text border-transparent opacity-70 hover:opacity-100'}
        `}>
          <FileCode size={14} className={readOnly ? "text-orange-400" : "text-blue-400"} />
          <span className="truncate">{label}</span>
          {value.length > 0 && !readOnly && (
            <div className="w-2 h-2 rounded-full bg-slate-400 ml-auto" />
          )}
          {readOnly && (
             <button onClick={handleCopy} className="ml-auto hover:text-white" title="Copy">
               {copied ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
             </button>
          )}
          {!readOnly && onClear && value.length > 0 && (
             <button onClick={onClear} className="ml-auto hover:text-white" title="Clear">
               <X size={14} />
             </button>
          )}
        </div>

        {/* Empty space filler for tab bar */}
        <div className="flex-1 h-full bg-vscode-light-tab dark:bg-vscode-dark-tab"></div>
      </div>

      {/* Editor Body */}
      <div className="flex-1 relative overflow-hidden">
        <Editor
          height="100%"
          defaultLanguage="html"
          value={value}
          theme={isDarkMode ? 'vs-dark' : 'light'}
          onChange={onChange}
          loading={
            <div className="flex items-center justify-center h-full text-slate-500 text-xs">
              Loading Editor...
            </div>
          }
          options={{
            readOnly: readOnly,
            minimap: { enabled: false },
            fontSize: 13,
            fontFamily: "'Consolas', 'Monaco', 'Courier New', monospace",
            wordWrap: 'on',
            scrollBeyondLastLine: false,
            renderLineHighlight: 'none',
            lineNumbers: 'on',
            glyphMargin: false,
            folding: false,
            padding: { top: 16, bottom: 16 },
            cursorBlinking: 'smooth',
            smoothScrolling: true,
            contextmenu: false,
          }}
        />
