    >
      {active && <div className="absolute left-0 top-0 bottom-0 w-[2px] bg-primary"></div>}
      <Icon size={24} strokeWidth={1.5} />
    </button>
  );

  return (
    <div className={`flex flex-col h-screen w-screen overflow-hidden text-sm bg-vscode-light-bg dark:bg-vscode-dark-bg text-vscode-light-textActive dark:text-vscode-dark-textActive`}>

      {/* Top Main Window (Flex Row) */}
      <div className="flex-1 flex overflow-hidden">

        {/* 1. Activity Bar (Leftmost) */}
        <div className="w-12 flex flex-col items-center bg-vscode-light-activity dark:bg-vscode-dark-activity text-slate-400 py-2 flex-shrink-0 z-20">
          {/* Icons removed as requested */}

          <div className="flex-1"></div>

          {/* Theme Toggle remains */}
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="w-10 h-10 flex items-center justify-center text-slate-400 hover:text-white rounded-lg mb-2"
          >
             {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        {/* 2. Sidebar Panel (Configuration) */}
        <div className="w-64 bg-vscode-light-sidebar dark:bg-vscode-dark-sidebar border-r border-vscode-light-border dark:border-vscode-dark-border flex flex-col flex-shrink-0">
          <div className="px-4 py-2.5 text-xs font-bold uppercase tracking-wider text-vscode-light-text dark:text-vscode-dark-text flex items-center justify-between">
            <span>Explorer</span>
            <MoreHorizontal size={16} />
          </div>

          {/* Section: Editors */}
          <div className="flex flex-col">
            <div className="px-2 py-1 flex items-center text-xs font-bold text-primary cursor-pointer">
              <span className="mr-1">▼</span> 
              <span>OPEN EDITORS</span>
            </div>
            <div className="flex flex-col">
               <div className="px-4 py-1 flex items-center gap-2 bg-vscode-light-hover dark:bg-vscode-dark-hover text-vscode-light-textActive dark:text-vscode-dark-textActive text-xs cursor-pointer">
                 <span className="text-blue-400">#</span> source.txt
               </div>
               <div className="px-4 py-1 flex items-center gap-2 text-vscode-light-text dark:text-vscode-dark-text hover:bg-vscode-light-hover dark:hover:bg-vscode-dark-hover text-xs cursor-pointer">
                 <span className="text-orange-400">&lt;&gt;</span> escaped.html
               </div>
            </div>
          </div>

          <div className="mt-4">
             <div className="px-2 py-1 flex items-center text-xs font-bold text-vscode-light-text dark:text-vscode-dark-text cursor-pointer">
              <span className="mr-1">▼</span> 
              <span>CONFIGURATION</span>
            </div>
            <SettingsPanel settings={settings} onUpdate={handleUpdateSetting} />
          </div>

          <div className="mt-auto p-4 border-t border-vscode-light-border dark:border-vscode-dark-border">
             <div className="px-2 py-1 flex items-center text-xs font-bold text-vscode-light-text dark:text-vscode-dark-text cursor-pointer mb-2">
              <span className="mr-1">▼</span> 
              <span>ACTIONS</span>
            </div>
             <div className="grid grid-cols-2 gap-2">
                <button onClick={handleEscape} className="bg-primary hover:bg-primaryHover text-white py-1 px-2 text-xs rounded-sm">
                   Encode
                </button>
                <button onClick={handleUnescape} className="bg-vscode-light-hover dark:bg-vscode-dark-hover hover:brightness-110 border border-vscode-light-border dark:border-vscode-dark-border py-1 px-2 text-xs rounded-sm">
                   Decode
                </button>
                <button onClick={swapContent} className="col-span-2 flex items-center justify-center gap-1 py-1 text-xs text-vscode-light-text dark:text-vscode-dark-text hover:text-vscode-light-textActive dark:hover:text-vscode-dark-textActive">
                   <ArrowRightLeft size={10} /> Swap
                </button>
                 <button onClick={clearAll} className="col-span-2 flex items-center justify-center gap-1 py-1 text-xs text-red-400 hover:text-red-300">
                   <XCircle size={10} /> Clear All
                </button>
             </div>
          </div>
        </div>

        {/* 3. Main Editor Area */}
        <div className="flex-1 flex flex-col bg-vscode-light-bg dark:bg-vscode-dark-bg overflow-hidden relative">

          {/* Breadcrumbs (Visual Only) */}
          <div className="h-6 flex items-center px-4 bg-vscode-light-bg dark:bg-vscode-dark-bg text-xs text-vscode-light-text dark:text-vscode-dark-text border-b border-vscode-light-border dark:border-vscode-dark-border">
             <span>src</span>
             <span className="mx-1">›</span>
             <span>components</span>
             <span className="mx-1">›</span>
             <span className="text-vscode-light-textActive dark:text-vscode-dark-textActive">Converter.tsx</span>
          </div>

          {/* Editor Grid */}
          <div className="flex-1 grid grid-cols-1 md:grid-cols-2 h-full">
            <TextAreaCard 
              id="input"
              label="source.txt"
              value={inputText}
              onChange={(val) => setInputText(val || '')}
              isDarkMode={isDarkMode}
              placeholder="// Paste raw text here..."
            />
            <TextAreaCard 
              id="output"
              label="escaped.html"
              value={outputText}
              readOnly
              onClear={() => setOutputText('')}
              isActive={false} // Just for visual distinction in tabs
              isDarkMode={isDarkMode}
              placeholder="<!-- Result will appear here -->"
            />
          </div>
        </div>

      </div>

      {/* 4. Status Bar */}
      <div className="h-6 bg-vscode-light-status dark:bg-vscode-dark-status flex items-center px-3 text-xs text-white justify-between select-none">
        <div className="flex items-center gap-4">
           <div className="flex items-center gap-1 cursor-pointer hover:bg-white/10 px-1 rounded">
             <Split size={12} />
             <span>main*</span>
           </div>
           <div className="flex items-center gap-1 hover:bg-white/10 px-1 rounded cursor-pointer">
              <CheckCircle2 size={12} />
              <span>0 Errors</span>
           </div>
        </div>

        <div className="flex items-center gap-4">
           <div className="cursor-pointer hover:bg-white/10 px-1 rounded">
             Ln {inputText.split('\n').length}, Col {inputText.length}
           </div>
           <div className="cursor-pointer hover:bg-white/10 px-1 rounded">UTF-8</div>
           <div className="cursor-pointer hover:bg-white/10 px-1 rounded">
             {mode === EscapeMode.FULL ? 'Full Escape' : 'Smart Mode'}
           </div>
           <div className="cursor-pointer hover:bg-white/10 px-1 rounded">
              HTML
           </div>
           <div className="cursor-pointer hover:bg-white/10 px-1 rounded">
             Prettier
           </div>
        </div>
      </div>

    </div>
  );
};

export default App;
